import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"图像 (Images)","description":"","frontmatter":{},"headers":[],"relativePath":"image.md","filePath":"image.md","lastUpdated":1682738613000}'),l={name:"image.md"};function p(o,e,t,c,d,r){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="图像-images" tabindex="-1">图像 (Images)</h1><hr><p style="font:italic 1em sans-serif;color:#78909C;">此章节待补充或完善...</p><p style="font:italic 1em sans-serif;color:#78909C;">Marked by SuperMonster003 on Oct 22, 2022.</p><hr><p>images模块提供了一些手机设备中常见的图片处理函数, 包括截图、读写图片、图片剪裁、旋转、二值化、找色找图等.</p><p>该模块分为两个部分, 找图找色部分和图片处理部分.</p><p>需要注意的是, image对象创建后尽量在不使用时进行回收, 同时避免循环创建大量图片. 因为图片是一种占用内存比较大的资源, 尽管Auto.js通过各种方式（比如图片缓存机制、垃圾回收时回收图片、脚本结束时回收所有图片）尽量降低图片资源的泄漏和内存占用, 但是糟糕的代码仍然可以占用大量内存.</p><p>Image对象通过调用<code>recycle()</code>函数来回收. 例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 读取图片</span></span>
<span class="line"><span>var img = images.read(&quot;./1.png&quot;);</span></span>
<span class="line"><span>//对图片进行操作</span></span>
<span class="line"><span>... </span></span>
<span class="line"><span>// 回收图片</span></span>
<span class="line"><span>img.recycle();</span></span></code></pre></div><p>例外的是, <code>captureScreen()</code> 返回的图片不需要回收.</p><h2 id="图片处理" tabindex="-1">图片处理</h2><h2 id="images-read-path" tabindex="-1">images.read(path)</h2><ul><li><code>path</code> {string} 图片路径</li></ul><p>读取在路径path的图片文件并返回一个Image对象. 如果文件不存在或者文件无法解码则返回null.</p><h2 id="images-load-url" tabindex="-1">images.load(url)</h2><ul><li><code>url</code> {string} 图片URL地址</li></ul><p>加载在地址URL的网络图片并返回一个Image对象. 如果地址不存在或者图片无法解码则返回null.</p><h2 id="images-copy-img" tabindex="-1">images.copy(img)</h2><ul><li><code>img</code> {Image} 图片</li><li>返回 {Image}</li></ul><p>复制一张图片并返回新的副本. 该函数会完全复制img对象的数据.</p><h2 id="images-save-image-path-format-png-quality-100" tabindex="-1">images.save(image, path[, format = &quot;png&quot;, quality = 100])</h2><ul><li><code>image</code> {Image} 图片</li><li><code>path</code> {string} 路径</li><li><code>format</code> {string} 图片格式, 可选的值为: <ul><li><code>png</code></li><li><code>jpeg</code>/<code>jpg</code></li><li><code>webp</code></li></ul></li><li><code>quality</code> {number} 图片质量, 为0~100的整数值</li></ul><p>把图片image以PNG格式保存到path中. 如果文件不存在会被创建；文件存在会被覆盖.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//把图片压缩为原来的一半质量并保存</span></span>
<span class="line"><span>var img = images.read(&quot;/sdcard/1.png&quot;);</span></span>
<span class="line"><span>images.save(img, &quot;/sdcard/1.jpg&quot;, &quot;jpg&quot;, 50);</span></span>
<span class="line"><span>app.viewFile(&quot;/sdcard/1.jpg&quot;);</span></span></code></pre></div><h2 id="images-frombase64-base64" tabindex="-1">images.fromBase64(base64)</h2><ul><li><code>base64</code> {string} 图片的Base64数据</li><li>返回 {Image}</li></ul><p>解码Base64数据并返回解码后的图片Image对象. 如果base64无法解码则返回<code>null</code>.</p><h2 id="images-tobase64-img-format-png-quality-100" tabindex="-1">images.toBase64(img[, format = &quot;png&quot;, quality = 100])</h2><ul><li><code>image</code> {image} 图片</li><li><code>format</code> {string} 图片格式, 可选的值为: <ul><li><code>png</code></li><li><code>jpeg</code>/<code>jpg</code></li><li><code>webp</code></li></ul></li><li><code>quality</code> {number} 图片质量, 为0~100的整数值</li><li>返回 {string}</li></ul><p>把图片编码为base64数据并返回.</p><h2 id="images-frombytes-bytes" tabindex="-1">images.fromBytes(bytes)</h2><ul><li><code>bytes</code> {byte[]} 字节数组</li></ul><p>解码字节数组bytes并返回解码后的图片Image对象. 如果bytes无法解码则返回<code>null</code>.</p><h2 id="images-tobytes-img-format-png-quality-100" tabindex="-1">images.toBytes(img[, format = &quot;png&quot;, quality = 100])</h2><ul><li><code>image</code> {image} 图片</li><li><code>format</code> {string} 图片格式, 可选的值为: <ul><li><code>png</code></li><li><code>jpeg</code>/<code>jpg</code></li><li><code>webp</code></li></ul></li><li><code>quality</code> {number} 图片质量, 为0~100的整数值</li><li>返回 {byte[]}</li></ul><p>把图片编码为字节数组并返回.</p><h2 id="images-clip-img-x-y-w-h" tabindex="-1">images.clip(img, x, y, w, h)</h2><ul><li><code>img</code> {Image} 图片</li><li><code>x</code> {number} 剪切区域的左上角横坐标</li><li><code>y</code> {number} 剪切区域的左上角纵坐标</li><li><code>w</code> {number} 剪切区域的宽度</li><li><code>h</code> {number} 剪切区域的高度</li><li>返回 {Image}</li></ul><p>从图片img的位置(x, y)处剪切大小为w * h的区域, 并返回该剪切区域的新图片.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var src = images.read(&quot;/sdcard/1.png&quot;);</span></span>
<span class="line"><span>var clip = images.clip(src, 100, 100, 400, 400);</span></span>
<span class="line"><span>images.save(clip, &quot;/sdcard/clip.png&quot;);</span></span></code></pre></div><h2 id="images-resize-img-size-interpolation" tabindex="-1">images.resize(img, size[, interpolation])</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><p><code>img</code> {Image} 图片</p></li><li><p><code>size</code> {Array} 两个元素的数组[w, h], 分别表示宽度和高度；如果只有一个元素, 则宽度和高度相等</p></li><li><p><code>interpolation</code> {string} 插值方法, 可选, 默认为&quot;LINEAR&quot;（线性插值）, 可选的值有：</p><ul><li><code>NEAREST</code> 最近邻插值</li><li><code>LINEAR</code> 线性插值（默认）</li><li><code>AREA</code> 区域插值</li><li><code>CUBIC</code> 三次样条插值</li><li><code>LANCZOS4</code> Lanczos插值 参见<a href="https://docs.opencv.org/3.4.4/da/d54/group__imgproc__transform.html#ga5bb5a1fea74ea38e1a5445ca803ff121/" target="_blank" rel="noreferrer">InterpolationFlags</a></li></ul></li><li><p>返回 {Image}</p></li></ul><p>调整图片大小, 并返回调整后的图片. 例如把图片放缩为200*300：<code>images.resize(img, [200, 300])</code>.</p><p>参见<a href="https://docs.opencv.org/3.4.4/da/d54/group__imgproc__transform.html#ga47a974309e9102f5f08231edc7e7529d/" target="_blank" rel="noreferrer">Imgproc.resize</a>.</p><h2 id="images-scale-img-fx-fy-interpolation" tabindex="-1">images.scale(img, fx, fy[, interpolation])</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><p><code>img</code> {Image} 图片</p></li><li><p><code>fx</code> {number} 宽度放缩倍数</p></li><li><p><code>fy</code> {number} 高度放缩倍数</p></li><li><p><code>interpolation</code> {string} 插值方法, 可选, 默认为&quot;LINEAR&quot;（线性插值）, 可选的值有：</p><ul><li><code>NEAREST</code> 最近邻插值</li><li><code>LINEAR</code> 线性插值（默认）</li><li><code>AREA</code> 区域插值</li><li><code>CUBIC</code> 三次样条插值</li><li><code>LANCZOS4</code> Lanczos插值 参见<a href="https://docs.opencv.org/3.4.4/da/d54/group__imgproc__transform.html#ga5bb5a1fea74ea38e1a5445ca803ff121/" target="_blank" rel="noreferrer">InterpolationFlags</a></li></ul></li><li><p>返回 {Image}</p></li></ul><p>放缩图片, 并返回放缩后的图片. 例如把图片变成原来的一半：<code>images.scale(img, 0.5, 0.5)</code>.</p><p>参见<a href="https://docs.opencv.org/3.4.4/da/d54/group__imgproc__transform.html#ga47a974309e9102f5f08231edc7e7529d/" target="_blank" rel="noreferrer">Imgproc.resize</a>.</p><h2 id="images-rotate-img-degree-x-y" tabindex="-1">images.rotate(img, degree[, x, y])</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>img</code> {Image} 图片</li><li><code>degree</code> {number} 旋转角度.</li><li><code>x</code> {number} 旋转中心x坐标, 默认为图片中点</li><li><code>y</code> {number} 旋转中心y坐标, 默认为图片中点</li><li>返回 {Image}</li></ul><p>将图片逆时针旋转 degree 度, 返回旋转后的图片对象.</p><p>例如逆时针旋转90度为<code>images.rotate(img, 90)</code>.</p><h2 id="images-concat-img1-image2-direction" tabindex="-1">images.concat(img1, image2[, direction])</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>img1</code> {Image} 图片1</li><li><code>img2</code> {Image} 图片2</li><li>direction {string} 连接方向, 默认为&quot;RIGHT&quot;, 可选的值有： <ul><li><code>LEFT</code> 将图片2接到图片1左边</li><li><code>RIGHT</code> 将图片2接到图片1右边</li><li><code>TOP</code> 将图片2接到图片1上边</li><li><code>BOTTOM</code> 将图片2接到图片1下边</li></ul></li><li>返回 {Image}</li></ul><p>连接两张图片, 并返回连接后的图像. 如果两张图片大小不一致, 小的那张将适当居中.</p><h2 id="images-grayscale-img" tabindex="-1">images.grayscale(img)</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>img</code> {Image} 图片</li><li>返回 {Image}</li></ul><p>灰度化图片, 并返回灰度化后的图片.</p><h2 id="image-threshold-img-threshold-maxval-type" tabindex="-1">image.threshold(img, threshold, maxVal[, type])</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><p><code>img</code> {Image} 图片</p></li><li><p><code>threshold</code> {number} 阈值</p></li><li><p><code>maxVal</code> {number} 最大值</p></li><li><p><code>type</code> {string} 阈值化类型, 默认为&quot;BINARY&quot;, 参见<a href="https://docs.opencv.org/3.4.4/d7/d1b/group__imgproc__misc.html#gaa9e58d2860d4afa658ef70a9b1115576/" target="_blank" rel="noreferrer">ThresholdTypes</a>, 可选的值:</p><ul><li><code>BINARY</code></li><li><code>BINARY_INV</code></li><li><code>TRUNC</code></li><li><code>TOZERO</code></li><li><code>TOZERO_INV</code></li><li><code>OTSU</code></li><li><code>TRIANGLE</code></li></ul></li><li><p>返回 {Image}</p></li></ul><p>将图片阈值化, 并返回处理后的图像. 可以用这个函数进行图片二值化. 例如：<code>images.threshold(img, 100, 255, &quot;BINARY&quot;)</code>, 这个代码将图片中大于100的值全部变成255, 其余变成0, 从而达到二值化的效果. 如果img是一张灰度化图片, 这个代码将会得到一张黑白图片.</p><p>可以参考有关博客（比如<a href="https://blog.csdn.net/u012566751/article/details/77046445/" target="_blank" rel="noreferrer">threshold函数的使用</a>）或者OpenCV文档<a href="https://docs.opencv.org/3.4.4/d7/d1b/group__imgproc__misc.html#gae8a4a146d1ca78c626a53577199e9c57/" target="_blank" rel="noreferrer">threshold</a>.</p><h2 id="images-adaptivethreshold-img-maxvalue-adaptivemethod-thresholdtype-blocksize-c" tabindex="-1">images.adaptiveThreshold(img, maxValue, adaptiveMethod, thresholdType, blockSize, C)</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>img</code> {Image} 图片</li><li><code>maxValue</code> {number} 最大值</li><li><code>adaptiveMethod</code> {string} 在一个邻域内计算阈值所采用的算法, 可选的值有： <ul><li><code>MEAN_C</code> 计算出领域的平均值再减去参数C的值</li><li><code>GAUSSIAN_C</code> 计算出领域的高斯均值再减去参数C的值</li></ul></li><li><code>thresholdType</code> {string} 阈值化类型, 可选的值有： <ul><li><code>BINARY</code></li><li><code>BINARY_INV</code></li></ul></li><li><code>blockSize</code> {number} 邻域块大小</li><li><code>C</code> {number} 偏移值调整量</li><li>返回 {Image}</li></ul><p>对图片进行自适应阈值化处理, 并返回处理后的图像.</p><p>可以参考有关博客（比如<a href="https://blog.csdn.net/guduruyu/article/details/68059450/" target="_blank" rel="noreferrer">threshold与adaptiveThreshold</a>）或者OpenCV文档[adaptiveThreshold](<a href="https://docs.opencv.org/3.4.4/d7/d1b/group__imgproc__misc.html#ga72b913f352e4a1b1b397736707afcde3" target="_blank" rel="noreferrer">https://docs.opencv.org/3.4.4/d7/d1b/group__imgproc__misc.html#ga72b913f352e4a1b1b397736707afcde3</a> /).</p><h2 id="images-cvtcolor-img-code-dstcn" tabindex="-1">images.cvtColor(img, code[, dstCn])</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>img</code> {Image} 图片</li><li><code>code</code> {string} 颜色空间转换的类型, 可选的值有一共有205个（参见<a href="https://docs.opencv.org/3.4.4/d8/d01/group__imgproc__color__conversions.html#ga4e0972be5de079fed4e3a10e24ef5ef0/" target="_blank" rel="noreferrer">ColorConversionCodes</a>）, 这里只列出几个： <ul><li><code>BGR2GRAY</code> BGR转换为灰度</li><li><code>BGR2HSV </code> BGR转换为HSV</li><li>\`\`</li></ul></li><li><code>dstCn</code> {number} 目标图像的颜色通道数量, 如果不填写则根据其他参数自动决定.</li><li>返回 {Image}</li></ul><p>对图像进行颜色空间转换, 并返回转换后的图像.</p><p>可以参考有关博客（比如<a href="https://blog.csdn.net/u011574296/article/details/70896811?locationNum=14&amp;fps=1" target="_blank" rel="noreferrer">颜色空间转换</a>）或者OpenCV文档<a href="https://docs.opencv.org/3.4.4/d8/d01/group__imgproc__color__conversions.html#ga397ae87e1288a81d2363b61574eb8cab/" target="_blank" rel="noreferrer">cvtColor</a>.</p><h2 id="images-inrange-img-lowerbound-upperbound" tabindex="-1">images.inRange(img, lowerBound, upperBound)</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>img</code> {Image} 图片</li><li><code>lowerBound</code> {string} | {number} 颜色下界</li><li><code>upperBound</code> {string} | {number} 颜色下界</li><li>返回 {Image}</li></ul><p>将图片二值化, 在lowerBound~upperBound范围以外的颜色都变成0, 在范围以内的颜色都变成255.</p><p>例如<code>images.inRange(img, &quot;#000000&quot;, &quot;#222222&quot;)</code>.</p><h2 id="images-interval-img-color-interval" tabindex="-1">images.interval(img, color, interval)</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>img</code> {Image} 图片</li><li><code>color</code> {string} | {number} 颜色值</li><li><code>interval</code> {number} 每个通道的范围间隔</li><li>返回 {Image}</li></ul><p>将图片二值化, 在color-interval ~ color+interval范围以外的颜色都变成0, 在范围以内的颜色都变成255. 这里对color的加减是对每个通道而言的.</p><p>例如<code>images.interval(img, &quot;#888888&quot;, 16)</code>, 每个通道的颜色值均为0x88, 加减16后的范围是[0x78, 0x98], 因此这个代码将把#787878~#989898的颜色变成#FFFFFF, 而把这个范围以外的变成#000000.</p><h2 id="images-blur-img-size-anchor-type" tabindex="-1">images.blur(img, size[, anchor, type])</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>img</code> {Image} 图片</li><li><code>size</code> {Array} 定义滤波器的大小, 如[3, 3]</li><li><code>anchor</code> {Array} 指定锚点位置(被平滑点), 默认为图像中心</li><li><code>type</code> {string} 推断边缘像素类型, 默认为&quot;DEFAULT&quot;, 可选的值有： <ul><li><code>CONSTANT</code> iiiiii|abcdefgh|iiiiiii with some specified i</li><li><code>REPLICATE</code> aaaaaa|abcdefgh|hhhhhhh</li><li><code>REFLECT</code> fedcba|abcdefgh|hgfedcb</li><li><code>WRAP</code> cdefgh|abcdefgh|abcdefg</li><li><code>REFLECT_101</code> gfedcb|abcdefgh|gfedcba</li><li><code>TRANSPARENT</code> uvwxyz|abcdefgh|ijklmno</li><li><code>REFLECT101</code> same as BORDER_REFLECT_101</li><li><code>DEFAULT</code> same as BORDER_REFLECT_101</li><li><code>ISOLATED</code> do not look outside of ROI</li></ul></li><li>返回 {Image}</li></ul><p>对图像进行模糊（平滑处理）, 返回处理后的图像.</p><p>可以参考有关博客（比如<a href="https://www.cnblogs.com/denny402/p/3848316.html" target="_blank" rel="noreferrer">实现图像平滑处理</a>）或者OpenCV文档<a href="https://docs.opencv.org/3.4.4/d4/d86/group__imgproc__filter.html#ga8c45db9afe636703801b0b2e440fce37/" target="_blank" rel="noreferrer">blur</a>.</p><h2 id="images-medianblur-img-size" tabindex="-1">images.medianBlur(img, size)</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>img</code> {Image} 图片</li><li><code>size</code> {number} 定义滤波器的大小, 正奇数, 如 3</li><li>返回 {Image}</li></ul><p>对图像进行中值滤波, 返回处理后的图像.</p><p>可以参考有关博客（比如<a href="https://www.cnblogs.com/denny402/p/3848316.html" target="_blank" rel="noreferrer">实现图像平滑处理</a>）或者OpenCV文档<a href="https://docs.opencv.org/3.4.4/d4/d86/group__imgproc__filter.html#ga564869aa33e58769b4469101aac458f9/" target="_blank" rel="noreferrer">blur</a>.</p><h2 id="images-gaussianblur-img-size-sigmax-sigmay-type" tabindex="-1">images.gaussianBlur(img, size[, sigmaX, sigmaY, type])</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>img</code> {Image} 图片</li><li><code>size</code> {Array} 定义滤波器的大小, 如[3, 3]</li><li><code>sigmaX</code> {number} x方向的标准方差, 不填写则自动计算</li><li><code>sigmaY</code> {number} y方向的标准方差, 不填写则自动计算</li><li><code>type</code> {string} 推断边缘像素类型, 默认为&quot;DEFAULT&quot;, 参见<code>images.blur</code></li><li>返回 {Image}</li></ul><p>对图像进行高斯模糊, 返回处理后的图像.</p><p>可以参考有关博客（比如<a href="https://www.cnblogs.com/denny402/p/3848316.html" target="_blank" rel="noreferrer">实现图像平滑处理</a>）或者OpenCV文档<a href="https://docs.opencv.org/3.4.4/d4/d86/group__imgproc__filter.html#gaabe8c836e97159a9193fb0b11ac52cf1/" target="_blank" rel="noreferrer">GaussianBlur</a>.</p><h2 id="images-mattoimage-mat" tabindex="-1">images.matToImage(mat)</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>mat</code> {Mat} OpenCV的Mat对象</li><li>返回 {Image}</li></ul><p>把Mat对象转换为Image对象.</p><h2 id="找图找色" tabindex="-1">找图找色</h2><h2 id="images-requestscreencapture-landscape" tabindex="-1">images.requestScreenCapture([landscape])</h2><ul><li><code>landscape</code> {boolean} 布尔值, 表示将要执行的截屏是否为横屏. 如果landscape为false, 则表示竖屏截图; true为横屏截图.</li></ul><p>向系统申请屏幕截图权限, 返回是否请求成功.</p><p>第一次使用该函数会弹出截图权限请求, 建议选择“总是允许”.</p><p>这个函数只是申请截图权限, 并不会真正执行截图, 真正的截图函数是<code>captureScreen()</code>.</p><p>该函数在截图脚本中只需执行一次, 而无需每次调用<code>captureScreen()</code>都调用一次.</p><p><strong>如果不指定landscape值, 则截图方向由当前设备屏幕方向决定</strong>, 因此务必注意执行该函数时的屏幕方向.</p><p>建议在本软件界面运行该函数, 在其他软件界面运行时容易出现一闪而过的黑屏现象.</p><p>示例:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//请求截图</span></span>
<span class="line"><span>if(!requestScreenCapture()){</span></span>
<span class="line"><span>    toast(&quot;请求截图失败&quot;);</span></span>
<span class="line"><span>    exit();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>//连续截图10张图片(间隔1秒)并保存到存储卡目录</span></span>
<span class="line"><span>for(var i = 0; i &lt; 10; i++){</span></span>
<span class="line"><span>    captureScreen(&quot;/sdcard/screencapture&quot; + i + &quot;.png&quot;);</span></span>
<span class="line"><span>    sleep(1000);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>该函数也可以作为全局函数使用.</p><h2 id="images-capturescreen" tabindex="-1">images.captureScreen()</h2><p>截取当前屏幕并返回一个Image对象.</p><p>没有截图权限时执行该函数会抛出SecurityException.</p><p>该函数不会返回null, 两次调用可能返回相同的Image对象. 这是因为设备截图的更新需要一定的时间, 短时间内（一般来说是16ms）连续调用则会返回同一张截图.</p><p>截图需要转换为Bitmap格式, 从而该函数执行需要一定的时间(0~20ms).</p><p>另外在requestScreenCapture()执行成功后需要一定时间后才有截图可用, 因此如果立即调用captureScreen(), 会等待一定时间后(一般为几百ms)才返回截图.</p><p>例子:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//请求横屏截图</span></span>
<span class="line"><span>requestScreenCapture(true);</span></span>
<span class="line"><span>//截图</span></span>
<span class="line"><span>var img = captureScreen();</span></span>
<span class="line"><span>//获取在点(100, 100)的颜色值</span></span>
<span class="line"><span>var color = images.pixel(img, 100, 100);</span></span>
<span class="line"><span>//显示该颜色值</span></span>
<span class="line"><span>toast(colors.toString(color));</span></span></code></pre></div><p>该函数也可以作为全局函数使用.</p><h2 id="images-capturescreen-path" tabindex="-1">images.captureScreen(path)</h2><ul><li><code>path</code> {string} 截图保存路径</li></ul><p>截取当前屏幕并以PNG格式保存到path中. 如果文件不存在会被创建；文件存在会被覆盖.</p><p>该函数不会返回任何值. 该函数也可以作为全局函数使用.</p><h2 id="images-pixel-image-x-y" tabindex="-1">images.pixel(image, x, y)</h2><ul><li><code>image</code> {Image} 图片</li><li><code>x</code> {number} 要获取的像素的横坐标.</li><li><code>y</code> {number} 要获取的像素的纵坐标.</li></ul><p>返回图片image在点(x, y)处的像素的ARGB值.</p><p>该值的格式为0xAARRGGBB, 是一个&quot;32位整数&quot;(虽然JavaScript中并不区分整数类型和其他数值类型).</p><p>坐标系以图片左上角为原点. 以图片左侧边为y轴, 上侧边为x轴.</p><h2 id="images-findcolor-image-color-options" tabindex="-1">images.findColor(image, color, options)</h2><ul><li><code>image</code> {Image} 图片</li><li><code>color</code> {number} | {string} 要寻找的颜色的RGB值. 如果是一个整数, 则以0xRRGGBB的形式代表RGB值（A通道会被忽略）；如果是字符串, 则以&quot;#RRGGBB&quot;代表其RGB值.</li><li><code>options</code> {Object} 选项</li></ul><p>在图片中寻找颜色color. 找到时返回找到的点Point, 找不到时返回null.</p><p>选项包括：</p><ul><li><code>region</code> {Array} 找色区域. 是一个两个或四个元素的数组. (region[0], region[1])表示找色区域的左上角；region[2]*region[3]表示找色区域的宽高. 如果只有region只有两个元素, 则找色区域为(region[0], region[1])到屏幕右下角. 如果不指定region选项, 则找色区域为整张图片.</li><li><code>threshold</code> {number} 找色时颜色相似度的临界值, 范围为0~255（越小越相似, 0为颜色相等, 255为任何颜色都能匹配）. 默认为4. threshold和浮点数相似度(0.0~1.0)的换算为 similarity = (255 - threshold) / 255.</li></ul><p>该函数也可以作为全局函数使用.</p><p>一个循环找色的例子如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>requestScreenCapture();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//循环找色, 找到红色(#ff0000)时停止并报告坐标</span></span>
<span class="line"><span>while(true){</span></span>
<span class="line"><span>    var img = captureScreen();</span></span>
<span class="line"><span>    var point = findColor(img, &quot;#ff0000&quot;);</span></span>
<span class="line"><span>    if(point){</span></span>
<span class="line"><span>        toast(&quot;找到红色, 坐标为(&quot; + point.x + &quot;, &quot; + point.y + &quot;)&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>一个区域找色的例子如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//读取本地图片/sdcard/1.png</span></span>
<span class="line"><span>var img = images.read(&quot;/sdcard/1.png&quot;);</span></span>
<span class="line"><span>//判断图片是否加载成功</span></span>
<span class="line"><span>if(!img){</span></span>
<span class="line"><span>    toast(&quot;没有该图片&quot;);</span></span>
<span class="line"><span>    exit();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>//在该图片中找色, 指定找色区域为在位置(400, 500)的宽为300长为200的区域, 指定找色临界值为4</span></span>
<span class="line"><span>var point = findColor(img, &quot;#00ff00&quot;, {</span></span>
<span class="line"><span>     region: [400, 500, 300, 200],</span></span>
<span class="line"><span>     threshold: 4</span></span>
<span class="line"><span> });</span></span>
<span class="line"><span>if(point){</span></span>
<span class="line"><span>    toast(&quot;找到啦:&quot; + point);</span></span>
<span class="line"><span>}else{</span></span>
<span class="line"><span>    toast(&quot;没找到&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="images-findcolorinregion-img-color-x-y-width-height-threshold" tabindex="-1">images.findColorInRegion(img, color, x, y[, width, height, threshold])</h2><p>区域找色的简便方法.</p><p>相当于</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>images.findColor(img, color, {</span></span>
<span class="line"><span>     region: [x, y, width, height],</span></span>
<span class="line"><span>     threshold: threshold</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>该函数也可以作为全局函数使用.</p><h2 id="images-findcolorequals-img-color-x-y-width-height" tabindex="-1">images.findColorEquals(img, color[, x, y, width, height])</h2><ul><li><code>img</code> {Image} 图片</li><li><code>color</code> {number} | {string} 要寻找的颜色</li><li><code>x</code> {number} 找色区域的左上角横坐标</li><li><code>y</code> {number} 找色区域的左上角纵坐标</li><li><code>width</code> {number} 找色区域的宽度</li><li><code>height</code> {number} 找色区域的高度</li><li>返回 {Point}</li></ul><p>在图片img指定区域中找到颜色和color完全相等的某个点, 并返回该点的左边；如果没有找到, 则返回<code>null</code>.</p><p>找色区域通过<code>x</code>, <code>y</code>, <code>width</code>, <code>height</code>指定, 如果不指定找色区域, 则在整张图片中寻找.</p><p>该函数也可以作为全局函数使用.</p><p>示例： (通过找QQ红点的颜色来判断是否有未读消息)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>requestScreenCapture();</span></span>
<span class="line"><span>launchApp(&quot;QQ&quot;);</span></span>
<span class="line"><span>sleep(1200);</span></span>
<span class="line"><span>var p = findColorEquals(captureScreen(), &quot;#f64d30&quot;);</span></span>
<span class="line"><span>if(p){</span></span>
<span class="line"><span>    toast(&quot;有未读消息&quot;);</span></span>
<span class="line"><span>}else{</span></span>
<span class="line"><span>    toast(&quot;没有未读消息&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="images-findmulticolors-img-firstcolor-colors-options" tabindex="-1">images.findMultiColors(img, firstColor, colors[, options])</h2><ul><li><code>img</code> {Image} 要找色的图片</li><li><code>firstColor</code> {number} | {string} 第一个点的颜色</li><li><code>colors</code> {Array} 表示剩下的点相对于第一个点的位置和颜色的数组, 数组的每个元素为[x, y, color]</li><li><code>options</code> {Object} 选项, 包括： <ul><li><code>region</code> {Array} 找色区域. 是一个两个或四个元素的数组. (region[0], region[1])表示找色区域的左上角；region[2]*region[3]表示找色区域的宽高. 如果只有region只有两个元素, 则找色区域为(region[0], region[1])到屏幕右下角. 如果不指定region选项, 则找色区域为整张图片.</li><li><code>threshold</code> {number} 找色时颜色相似度的临界值, 范围为0~255（越小越相似, 0为颜色相等, 255为任何颜色都能匹配）. 默认为4. threshold和浮点数相似度(0.0~1.0)的换算为 similarity = (255 - threshold) / 255.</li></ul></li></ul><p>多点找色, 类似于按键精灵的多点找色, 其过程如下：</p><ol><li>在图片img中找到颜色firstColor的位置(x0, y0)</li><li>对于数组colors的每个元素[x, y, color], 检查图片img在位置(x + x0, y + y0)上的像素是否是颜色color, 是的话返回(x0, y0), 否则继续寻找firstColor的位置, 重新执行第1步</li><li>整张图片都找不到时返回<code>null</code></li></ol><p>例如, 对于代码<code>images.findMultiColors(img, &quot;#123456&quot;, [[10, 20, &quot;#ffffff&quot;], [30, 40, &quot;#000000&quot;]])</code>, 假设图片在(100, 200)的位置的颜色为#123456, 这时如果(110, 220)的位置的颜色为#fffff且(130, 240)的位置的颜色为#000000, 则函数返回点(100, 200).</p><p>如果要指定找色区域, 则在options中指定, 例如:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var p = images.findMultiColors(img, &quot;#123456&quot;, [[10, 20, &quot;#ffffff&quot;], [30, 40, &quot;#000000&quot;]], {</span></span>
<span class="line"><span>    region: [0, 960, 1080, 960]</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="images-detectscolor-image-color-x-y-threshold-16-algorithm-diff" tabindex="-1">images.detectsColor(image, color, x, y[, threshold = 16, algorithm = &quot;diff&quot;])</h2><ul><li><code>image</code> {Image} 图片</li><li><code>color</code> {number} | {string} 要检测的颜色</li><li><code>x</code> {number} 要检测的位置横坐标</li><li><code>y</code> {number} 要检测的位置纵坐标</li><li><code>threshold</code> {number} 颜色相似度临界值, 默认为16. 取值范围为0~255.</li><li><code>algorithm</code> {string} 颜色匹配算法, 包括: <ul><li><p>&quot;equal&quot;: 相等匹配, 只有与给定颜色color完全相等时才匹配.</p></li><li><p>&quot;diff&quot;: 差值匹配. 与给定颜色的R、G、B差的绝对值之和小于threshold时匹配.</p></li><li><p>&quot;rgb&quot;: rgb欧拉距离相似度. 与给定颜色color的rgb欧拉距离小于等于threshold时匹配.</p></li><li><p>&quot;rgb+&quot;: 加权rgb欧拉距离匹配(<a href="https://en.wikipedia.org/wiki/Color_difference/" target="_blank" rel="noreferrer">LAB Delta E</a>).</p></li><li><p>&quot;hs&quot;: hs欧拉距离匹配. hs为HSV空间的色调值.</p></li></ul></li></ul><p>返回图片image在位置(x, y)处是否匹配到颜色color. 用于检测图片中某个位置是否是特定颜色.</p><p>一个判断微博客户端的某个微博是否被点赞过的例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>requestScreenCapture();</span></span>
<span class="line"><span>//找到点赞控件</span></span>
<span class="line"><span>var like = id(&quot;ly_feed_like_icon&quot;).findOne();</span></span>
<span class="line"><span>//获取该控件中点坐标</span></span>
<span class="line"><span>var x = like.bounds().centerX();</span></span>
<span class="line"><span>var y = like.bounds().centerY();</span></span>
<span class="line"><span>//截图</span></span>
<span class="line"><span>var img = captureScreen();</span></span>
<span class="line"><span>//判断在该坐标的颜色是否为橙红色</span></span>
<span class="line"><span>if(images.detectsColor(img, &quot;#fed9a8&quot;, x, y)){</span></span>
<span class="line"><span>    //是的话则已经是点赞过的了, 不做任何动作</span></span>
<span class="line"><span>}else{</span></span>
<span class="line"><span>    //否则点击点赞按钮</span></span>
<span class="line"><span>    like.click();</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="images-findimage-img-template-options" tabindex="-1">images.findImage(img, template[, options])</h2><ul><li><code>img</code> {Image} 大图片</li><li><code>template</code> {Image} 小图片（模板）</li><li><code>options</code> {Object} 找图选项</li></ul><p>找图. 在大图片img中查找小图片template的位置（模块匹配）, 找到时返回位置坐标(Point), 找不到时返回null.</p><p>选项包括：</p><ul><li><code>threshold</code> {number} 图片相似度. 取值范围为0~1的浮点数. 默认值为0.9.</li><li><code>region</code> {Array} 找图区域. 参见findColor函数关于region的说明.</li><li><code>level</code> {number} <strong>一般而言不必修改此参数</strong>. 不加此参数时该参数会根据图片大小自动调整. 找图算法是采用图像金字塔进行的, level参数表示金字塔的层次, level越大可能带来越高的找图效率, 但也可能造成找图失败（图片因过度缩小而无法分辨）或返回错误位置. 因此, 除非您清楚该参数的意义并需要进行性能调优, 否则不需要用到该参数.</li></ul><p>该函数也可以作为全局函数使用.</p><p>一个最简单的找图例子如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var img = images.read(&quot;/sdcard/大图.png&quot;);</span></span>
<span class="line"><span>var templ = images.read(&quot;/sdcard/小图.png&quot;);</span></span>
<span class="line"><span>var p = findImage(img, templ);</span></span>
<span class="line"><span>if(p){</span></span>
<span class="line"><span>    toast(&quot;找到啦:&quot; + p);</span></span>
<span class="line"><span>}else{</span></span>
<span class="line"><span>    toast(&quot;没找到&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>稍微复杂点的区域找图例子如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto();</span></span>
<span class="line"><span>requestScreenCapture();</span></span>
<span class="line"><span>var wx = images.read(&quot;/sdcard/微信图标.png&quot;);</span></span>
<span class="line"><span>//返回桌面</span></span>
<span class="line"><span>home();</span></span>
<span class="line"><span>//截图并找图</span></span>
<span class="line"><span>var p = findImage(captureScreen(), wx, {</span></span>
<span class="line"><span>    region: [0, 50],</span></span>
<span class="line"><span>    threshold: 0.8</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>if(p){</span></span>
<span class="line"><span>    toast(&quot;在桌面找到了微信图标啦: &quot; + p);</span></span>
<span class="line"><span>}else{</span></span>
<span class="line"><span>    toast(&quot;在桌面没有找到微信图标&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="images-findimageinregion-img-template-x-y-width-height-threshold" tabindex="-1">images.findImageInRegion(img, template, x, y[, width, height, threshold])</h2><p>区域找图的简便方法. 相当于：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>images.findImage(img, template, {</span></span>
<span class="line"><span>    region: [x, y, width, height],</span></span>
<span class="line"><span>    threshold: threshold</span></span>
<span class="line"><span>})</span></span></code></pre></div><p>该函数也可以作为全局函数使用.</p><h2 id="images-matchtemplate-img-template-options" tabindex="-1">images.matchTemplate(img, template, options)</h2><p><strong>[v4.1.0新增]</strong></p><ul><li><code>img</code> {Image} 大图片</li><li><code>template</code> {Image} 小图片（模板）</li><li><code>options</code> {Object} 找图选项： <ul><li><code>threshold</code> {number} 图片相似度. 取值范围为0~1的浮点数. 默认值为0.9.</li><li><code>region</code> {Array} 找图区域. 参见findColor函数关于region的说明.</li><li><code>max</code> {number} 找图结果最大数量, 默认为5</li><li><code>level</code> {number} <strong>一般而言不必修改此参数</strong>. 不加此参数时该参数会根据图片大小自动调整. 找图算法是采用图像金字塔进行的, level参数表示金字塔的层次, level越大可能带来越高的找图效率, 但也可能造成找图失败（图片因过度缩小而无法分辨）或返回错误位置. 因此, 除非您清楚该参数的意义并需要进行性能调优, 否则不需要用到该参数.</li></ul></li><li>返回 {MatchingResult}</li></ul><p>在大图片中搜索小图片, 并返回搜索结果MatchingResult. 该函数可以用于找图时找出多个位置, 可以通过max参数控制最大的结果数量. 也可以对匹配结果进行排序、求最值等操作.</p><h1 id="matchingresult" tabindex="-1">MatchingResult</h1><p><strong>[v4.1.0新增]</strong></p><h2 id="matches" tabindex="-1">matches</h2><ul><li>{Array} 匹配结果的数组.</li></ul><p>数组的元素是一个Match对象：</p><ul><li><code>point</code> {Point} 匹配位置</li><li><code>similarity</code> {number} 相似度</li></ul><p>例如:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var result = images.matchTemplate(img, template, {</span></span>
<span class="line"><span>    max: 100</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>result.matches.forEach(match =&gt; {</span></span>
<span class="line"><span>    log(&quot;point = &quot; + match.point + &quot;, similarity = &quot; + match.similarity);</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="points" tabindex="-1">points</h2><ul><li>{Array} 匹配位置的数组.</li></ul><h2 id="first" tabindex="-1">first()</h2><ul><li>返回 {Match}</li></ul><p>第一个匹配结果. 如果没有任何匹配, 则返回<code>null</code>.</p><h2 id="last" tabindex="-1">last()</h2><ul><li>返回 {Match}</li></ul><p>最后一个匹配结果. 如果没有任何匹配, 则返回<code>null</code>.</p><h2 id="leftmost" tabindex="-1">leftmost()</h2><ul><li>返回 {Match}</li></ul><p>位于大图片最左边的匹配结果. 如果没有任何匹配, 则返回<code>null</code>.</p><h2 id="topmost" tabindex="-1">topmost()</h2><ul><li>返回 {Match}</li></ul><p>位于大图片最上边的匹配结果. 如果没有任何匹配, 则返回<code>null</code>.</p><h2 id="rightmost" tabindex="-1">rightmost()</h2><ul><li>返回 {Match}</li></ul><p>位于大图片最右边的匹配结果. 如果没有任何匹配, 则返回<code>null</code>.</p><h2 id="bottommost" tabindex="-1">bottommost()</h2><ul><li>返回 {Match}</li></ul><p>位于大图片最下边的匹配结果. 如果没有任何匹配, 则返回<code>null</code>.</p><h2 id="best" tabindex="-1">best()</h2><ul><li>返回 {Match}</li></ul><p>相似度最高的匹配结果. 如果没有任何匹配, 则返回<code>null</code>.</p><h2 id="worst" tabindex="-1">worst()</h2><ul><li>返回 {Match}</li></ul><p>相似度最低的匹配结果. 如果没有任何匹配, 则返回<code>null</code>.</p><h2 id="sortby-cmp" tabindex="-1">sortBy(cmp)</h2><ul><li>cmp {Function}|{string} 比较函数, 或者是一个字符串表示排序方向. 例如&quot;left&quot;表示将匹配结果按匹配位置从左往右排序、&quot;top&quot;表示将匹配结果按匹配位置从上往下排序, &quot;left-top&quot;表示将匹配结果按匹配位置从左往右、从上往下排序. 方向包括<code>left</code>（左）, <code>top</code> （上）, <code>right</code> （右）, <code>bottom</code>（下）.</li><li>{MatchingResult}</li></ul><p>对匹配结果进行排序, 并返回排序后的结果.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var result = images.matchTemplate(img, template, {</span></span>
<span class="line"><span>    max: 100</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>log(result.sortBy(&quot;top-right&quot;));</span></span></code></pre></div><h1 id="image" tabindex="-1">Image</h1><p>表示一张图片, 可以是截图的图片, 或者本地读取的图片, 或者从网络获取的图片.</p><h2 id="image-getwidth" tabindex="-1">Image.getWidth()</h2><p>返回以像素为单位图片宽度.</p><h2 id="image-getheight" tabindex="-1">Image.getHeight()</h2><p>返回以像素为单位的图片高度.</p><h2 id="image-saveto-path" tabindex="-1">Image.saveTo(path)</h2><ul><li><code>path</code> {string} 路径</li></ul><p>把图片保存到路径path. （如果文件存在则覆盖）</p><h2 id="image-pixel-x-y" tabindex="-1">Image.pixel(x, y)</h2><ul><li><code>x</code> {number} 横坐标</li><li><code>y</code> {number} 纵坐标</li></ul><p>返回图片image在点(x, y)处的像素的ARGB值.</p><p>该值的格式为0xAARRGGBB, 是一个&quot;32位整数&quot;(虽然JavaScript中并不区分整数类型和其他数值类型).</p><p>坐标系以图片左上角为原点. 以图片左侧边为y轴, 上侧边为x轴.</p><h2 id="" tabindex="-1"></h2><h1 id="point" tabindex="-1">Point</h1><p>findColor, findImage返回的对象. 表示一个点（坐标）.</p><h2 id="point-x" tabindex="-1">Point.x</h2><p>横坐标.</p><h2 id="point-y" tabindex="-1">Point.y</h2><p>纵坐标.</p>`,249)])])}const u=a(l,[["render",p]]);export{m as __pageData,u as default};
